begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(35);
-- Synthetic identities share a phone across tenants intentionally.
insert into auth.users(id,email,raw_user_meta_data) values
 ('b6000000-0000-4000-8000-000000000021','hair-observation-owner-a@elifora.test','{}'),('b6000000-0000-4000-8000-000000000022','hair-observation-owner-b@elifora.test','{}'),
 ('b6000000-0000-4000-8000-000000000023','hair-observation-assistant@elifora.test','{}'),('b6000000-0000-4000-8000-000000000024','hair-observation-reception@elifora.test','{}');
