 ('b6000000-0000-4000-8000-000000000112','b6000000-0000-4000-8000-000000000002',null,'b6000000-0000-4000-8000-000000000022','owner','active',now()),
 ('b6000000-0000-4000-8000-000000000113','b6000000-0000-4000-8000-000000000001','b6000000-0000-4000-8000-000000000013','b6000000-0000-4000-8000-000000000023','assistant','active',now()),
 ('b6000000-0000-4000-8000-000000000114','b6000000-0000-4000-8000-000000000001','b6000000-0000-4000-8000-000000000011','b6000000-0000-4000-8000-000000000024','reception','active',now());
insert into public.clients(id,organization_id,full_name,phone,phone_normalized,created_by,updated_by,creation_location_id) values
 ('b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000001','Hair Client A','+905321234567','+905321234567','b6000000-0000-4000-8000-000000000021','b6000000-0000-4000-8000-000000000021','b6000000-0000-4000-8000-000000000011'),
 ('b6000000-0000-4000-8000-000000000032','b6000000-0000-4000-8000-000000000002','Hair Client B','+905321234567','+905321234567','b6000000-0000-4000-8000-000000000022','b6000000-0000-4000-8000-000000000022','b6000000-0000-4000-8000-000000000012'),
 ('b6000000-0000-4000-8000-000000000033','b6000000-0000-4000-8000-000000000001','Hair Client A Two','+905329999999','+905329999999','b6000000-0000-4000-8000-000000000021','b6000000-0000-4000-8000-000000000021','b6000000-0000-4000-8000-000000000011');




create temporary table results(name text primary key,value jsonb);
grant all on results to authenticated;
create function pg_temp.observe(payload jsonb,client uuid default 'b6000000-0000-4000-8000-000000000031',membership uuid default 'b6000000-0000-4000-8000-000000000111',location uuid default 'b6000000-0000-4000-8000-000000000011')
returns jsonb language sql volatile security invoker as $$
 select public.hair_observation_operation(membership,location,client,jsonb_build_object('request_id',gen_random_uuid())||payload,'b6000000-0000-4000-8000-000000000900');
$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','b6000000-0000-4000-8000-000000000021',true);

select public.hair_core_operation('b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011','b6000000-0000-4000-8000-000000000031','create_passport',jsonb_build_object('request_id',gen_random_uuid()));
select public.hair_core_operation('b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011','b6000000-0000-4000-8000-000000000033','create_passport',jsonb_build_object('request_id',gen_random_uuid()));
select set_config('request.jwt.claim.sub','b6000000-0000-4000-8000-000000000022',true);select public.hair_core_operation('b6000000-0000-4000-8000-000000000112','b6000000-0000-4000-8000-000000000012','b6000000-0000-4000-8000-000000000032','create_passport',jsonb_build_object('request_id',gen_random_uuid()));select set_config('request.jwt.claim.sub','b6000000-0000-4000-8000-000000000021',true);
insert into results values('ai',pg_temp.observe('{"request_id": "b6000000-0000-4000-8000-000000000901", "expected_version": 1, "technical": {"natural_level": {"state": "KNOWN", "value": 5}}, "evidence": {"source": "AI_ESTIMATE", "confidence": {"state": "KNOWN", "value": 0.75}}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011'));
select is((select value#>>'{data,observation,natural_level,value}' from results where name='ai'),'5','authorized whole-passport known observation');
select is((select value#>>'{data,observation,evidence,source}' from results where name='ai'),'AI_ESTIMATE','AI source is retained without any model call or verifier');
select is(pg_temp.observe('{"request_id": "b6000000-0000-4000-8000-000000000901", "expected_version": 1, "technical": {"natural_level": {"state": "KNOWN", "value": 5}}, "evidence": {"source": "AI_ESTIMATE", "confidence": {"state": "KNOWN", "value": 0.75}}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011'),(select value from results where name='ai'),'same request replays exact observation and evidence');
select ok((select count(*)=1 from public.hair_observations) and (select count(*)=1 from public.hair_evidence),'retry does not duplicate facts');
select is(public.hair_passport_snapshot('b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011','b6000000-0000-4000-8000-000000000031')#>'{data,core,observation}',(select value#>'{data,observation}' from results where name='ai'),'existing read contract exposes the newly selected observation');
insert into results values('regional',pg_temp.observe('{"request_id": "b6000000-0000-4000-8000-000000000902", "expected_version": 1, "technical": {"natural_level": {"state": "KNOWN", "value": 5}}, "evidence": {"source": "AI_ESTIMATE", "confidence": {"state": "KNOWN", "value": 0.75}}}'::jsonb||jsonb_build_object('region_id',(select id from public.hair_regions where client_id='b6000000-0000-4000-8000-000000000031' and region_type='ROOT'))));
select is((select value#>>'{data,observation,region_id}' from results where name='regional'),(select id::text from public.hair_regions where client_id='b6000000-0000-4000-8000-000000000031' and region_type='ROOT'),'regional observation remains attached to its passport region');
select is(pg_temp.observe('{"request_id": "b6000000-0000-4000-8000-000000000903", "expected_version": 2, "technical": {"natural_level": {"state": "KNOWN", "value": 5}}, "evidence": {"source": "PROFESSIONAL_VERIFIED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','INVALID_EVIDENCE','changing source string alone cannot upgrade AI evidence');
insert into results values('professional',pg_temp.observe('{"request_id": "b6000000-0000-4000-8000-000000000904", "expected_version": 2, "technical": {"natural_level": {"state": "KNOWN", "value": 6}}, "evidence": {"source": "PROFESSIONAL_VERIFIED", "attestation": "PERSONALLY_ASSESSED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011'));
select ok((select value#>>'{data,observation,evidence,verified_by}'='b6000000-0000-4000-8000-000000000021' and value#>>'{data,observation,evidence,observed_at,value}'=value#>>'{data,observation,evidence,recorded_at}' from results where name='professional'),'professional verifier and assessment time are server-derived');
select ok((select value#>>'{data,observation,supersedes_id}'=(select value#>>'{data,observation,id}' from results where name='ai') from results where name='professional') and (select source_type='AI_ESTIMATE' and verified_by is null from public.hair_evidence where id=(select (value#>>'{data,observation,evidence,id}')::uuid from results where name='ai')),'new professional assessment preserves previous AI attribution');
insert into results values('unknown',pg_temp.observe('{"expected_version": 3, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011'));
select ok((select value#>>'{data,observation,porosity,state}'='UNKNOWN' and value#>>'{data,observation,natural_level,state}'='NOT_ASSESSED' from results where name='unknown'),'unknown stays explicit and omitted fields are not copied into new evidence');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"natural_level": {"state": "KNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','INVALID_OBSERVATION','known value is required');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": "HIGH"}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','INVALID_OBSERVATION','unknown cannot retain a contradictory value');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"natural_level": {"state": "NOT_APPLICABLE", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','INVALID_OBSERVATION','unsupported not-applicable state rejected');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "INVENTED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','INVALID_EVIDENCE','source enum validated at database boundary');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "AI_ESTIMATE", "confidence": {"state": "KNOWN", "value": 1.01}}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','INVALID_CONFIDENCE','confidence above canonical range rejected');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "AI_ESTIMATE", "confidence": {"state": "UNKNOWN", "value": 0.5}}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','INVALID_CONFIDENCE','unknown confidence cannot contain a number');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "PROFESSIONAL_VERIFIED", "attestation": "PERSONALLY_ASSESSED", "verified_by": "b6000000-0000-4000-8000-000000000022"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','INVALID_EVIDENCE','arbitrary verifier cannot be supplied');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}, "organization_id": "b6000000-0000-4000-8000-000000000002"}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','VALIDATION_FAILED','ownership metadata is not accepted');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000032','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','CLIENT_NOT_FOUND','foreign passport is inaccessible');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}, "region_id": "b6000000-0000-4000-8000-000000000999"}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','HAIR_REGION_NOT_FOUND','foreign or unknown region is not disclosed');
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}'::jsonb||jsonb_build_object('region_id',(select id from public.hair_regions where client_id='b6000000-0000-4000-8000-000000000033' and region_type='ROOT')))->>'code','HAIR_REGION_NOT_FOUND','same-tenant other passport region cannot be attached');
select is(pg_temp.observe('{"request_id": "b6000000-0000-4000-8000-000000000901", "expected_version": 1, "technical": {"natural_level": {"state": "KNOWN", "value": 8}}, "evidence": {"source": "AI_ESTIMATE", "confidence": {"state": "KNOWN", "value": 0.75}}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','CONFLICT','idempotency key cannot change source payload');
select is(pg_temp.observe('{"expected_version": 1, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','CONFLICT','stale assessment cannot replace current state');
reset role;create temporary table counts_before as select (select count(*) from public.hair_evidence) e,(select count(*) from public.hair_observations) o,(select count(*) from public.audit_events) a,(select count(*) from app_private.hair_core_mutation_receipts) r;
create function pg_temp.reject_observation() returns trigger language plpgsql as $$begin raise exception using errcode='23514',message='Synthetic rollback';end$$;create trigger zz_test_reject before insert on public.hair_observations for each row when (new.technical_notes='Synthetic rollback') execute function pg_temp.reject_observation();set local role authenticated;
select is(pg_temp.observe('{"expected_version": 4, "technical": {"technical_notes": "Synthetic rollback"}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','INVALID_OBSERVATION','failure after evidence insertion returns stable error');
reset role;drop trigger zz_test_reject on public.hair_observations;
select ok((select e=(select count(*) from public.hair_evidence) and o=(select count(*) from public.hair_observations) and a=(select count(*) from public.audit_events) and r=(select count(*) from app_private.hair_core_mutation_receipts) from counts_before),'failed transaction leaves no evidence observation audit or receipt');
select ok(exists(select 1 from public.audit_events where action='hair_observation.created' and metadata->'fields' ? 'natural_level' and metadata->>'source_type'='AI_ESTIMATE') and exists(select 1 from public.audit_events where action='hair_evidence.created') and not exists(select 1 from public.audit_events where metadata ? 'technical' or metadata ? 'confidence'),'created audit identifies source and fields without sensitive values');
delete from public.role_permissions where role_code='owner' and permission_code='hair_passport.update';set local role authenticated;
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')#>>'{data,target_version}','5','add-observation permission alone can append and select current assessment');
set local role elifora_hair_writer;
select throws_ok($$update public.hair_passports set technical_notes='Forbidden edit' where client_id='b6000000-0000-4000-8000-000000000031'$$,'42501','technical write unavailable','selection permission does not grant core edits through RLS');
reset role;insert into public.role_permissions(role_code,permission_code) values('owner','hair_passport.update');set local role authenticated;
select public.hair_core_operation('b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011','b6000000-0000-4000-8000-000000000033','update_passport',jsonb_build_object('request_id',gen_random_uuid(),'expected_version',1,'technical','{"natural_level":{"state":"KNOWN","value":9}}'::jsonb));
select is(pg_temp.observe('{"expected_version": 2, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000033','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','CONFLICT','unverified state requires explicit replacement acknowledgement');
select is(pg_temp.observe('{"expected_version": 2, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}, "replace_unverified": true}','b6000000-0000-4000-8000-000000000033','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')#>>'{data,observation,natural_level,state}','NOT_ASSESSED','acknowledged selection clears overlay without laundering old values');
select is(pg_temp.observe('{"expected_version": 5, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "PHYSICAL_TEST", "observed_at": {"state": "KNOWN", "value": "2020-01-01T00:00:00Z"}, "context": "Synthetic external source"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')#>>'{data,observation,evidence,source}','PHYSICAL_TEST','PHYSICAL_TEST provenance accepted without creating external workflows');
select is(pg_temp.observe('{"expected_version": 6, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "HISTORICAL", "observed_at": {"state": "KNOWN", "value": "2020-01-01T00:00:00Z"}, "context": "Synthetic external source"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')#>>'{data,observation,evidence,source}','HISTORICAL','HISTORICAL provenance accepted without creating external workflows');
select ok((select count(*)=0 from public.hair_physical_tests) and (select count(*)=0 from public.hair_history_events),'no physical-test or technical-history writes');
select set_config('request.jwt.claim.sub','b6000000-0000-4000-8000-000000000023',true);
select is(pg_temp.observe('{"expected_version": 4, "technical": {"porosity": {"state": "UNKNOWN", "value": null}}, "evidence": {"source": "IMPORTED_UNVERIFIED"}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000113','b6000000-0000-4000-8000-000000000013')->>'code','FORBIDDEN','assistant cannot add observations');
select set_config('request.jwt.claim.sub','b6000000-0000-4000-8000-000000000021',true);reset role;update public.salon_memberships set status='revoked',revoked_at=now() where id='b6000000-0000-4000-8000-000000000111';set local role authenticated;
select is(pg_temp.observe('{"request_id": "b6000000-0000-4000-8000-000000000901", "expected_version": 1, "technical": {"natural_level": {"state": "KNOWN", "value": 5}}, "evidence": {"source": "AI_ESTIMATE", "confidence": {"state": "KNOWN", "value": 0.75}}}','b6000000-0000-4000-8000-000000000031','b6000000-0000-4000-8000-000000000111','b6000000-0000-4000-8000-000000000011')->>'code','MEMBERSHIP_REVOKED','revoked membership cannot replay prior success');
reset role;select * from finish();rollback;
